package com.enterpriseflow.controller; import com.enterpriseflow.api.ApiResponse; import com.enterpriseflow.service.SearchService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/search") public class SearchController {private final SearchService search;public SearchController(SearchService search){this.search=search;}@GetMapping public ApiResponse<Map<String,Object>> search(Authentication a,@RequestParam String q){return ApiResponse.success("Authorized search completed.",search.search(a.getName(),q));}}
